 const byId=new Map(db.songs.map(s=>[s.id,s]));
 const requested=new URLSearchParams(location.search).get('song');let stored='';
 try{stored=localStorage.getItem('rhythm-selected-song')||localStorage.getItem('rhythm-selected-song-v36')||''}catch{}
 const randomMode=requested==='random',rotationKey='rhythm-song-rotation-v52';let seen=[];
 if(randomMode)try{const saved=JSON.parse(localStorage.getItem(rotationKey)||'[]');if(Array.isArray(saved))seen=[...new Set(saved.filter(id=>byId.has(id)))]}catch{}
 let pool=db.songs.filter(s=>!seen.includes(s.id));if(!pool.length){seen=[];pool=db.songs;}
 // A cycle boundary must not replay the song that just ended.
 if(pool.length>1)pool=pool.filter(s=>s.id!==stored);
 const randomIndex=()=>{const a=new Uint32Array(1);if(typeof crypto!=='undefined'&&crypto.getRandomValues){crypto.getRandomValues(a);return a[0]%pool.length}return Math.floor(Math.random()*pool.length)};
 const current=randomMode?pool[randomIndex()]:byId.get(requested)||byId.get(stored)||byId.get(db.defaultSongId);
 if(randomMode)try{localStorage.setItem('rhythm-selected-song',current.id);localStorage.setItem(rotationKey,JSON.stringify([...seen,current.id]))}catch{}
